    AND (
        title LIKE CONCAT('%', #{keyword}, '%')
        OR location LIKE CONCAT('%', #{keyword}, '%')
        OR contact_name LIKE CONCAT('%', #{keyword}, '%')
        OR ticket_no = #{keyword}
    )



    AND due_time IS NOT NULL
    AND due_time < NOW()
    AND status IN (0, 10, 20)


    AND create_time >= #{createTimeFrom}


    AND create_time <= #{createTimeTo}

